def decode_chunks(chunks):
    # Own bounded two-octet big-endian LENGTH + raw payload protocol.
    # Empty input is a clean empty stream; an empty frame has header 00 00.
    if type(chunks) is not list or len(chunks)>32:
        raise ValueError("expected at most 32 chunks")
    if any(type(c) is not bytes or len(c)>32 for c in chunks):
        raise ValueError("expected bytes chunks of at most 32 octets")
    if sum(map(len,chunks))>256:
        raise ValueError("stream budget exceeded")
    pending=b""
    frames=[]
    for chunk in chunks:
        pending+=chunk
        while len(pending)>=2:
            size=int.from_bytes(pending[:2],"big")
            if size>8:
                raise ValueError("payload length exceeds 8")
            if len(pending)<2+size:
                break
            frames.append(pending[2:2+size])
            pending=pending[2+size:]
    if pending:
        raise ValueError("truncated frame at end of stream")
    return frames

wire=b"\x00\x03ABC\x00\x00\x00\x02XY"
print(decode_chunks([wire[:1],wire[1:4],wire[4:8],wire[8:]]))
print(decode_chunks([wire]))
try:
    decode_chunks([b"\x00\x03AB"])
except ValueError as error:
    print(error)

def advance_send(payload,offset,outcome):
    # Model ONE nonblocking stream send result, not a live socket call.
    if type(payload) is not bytes or len(payload)>64:
        raise ValueError("expected at most 64 payload octets")
    if type(offset) is not int or not 0<=offset<=len(payload):
        raise ValueError("invalid offset")
    if offset==len(payload):
        return offset,"done" # do not call send with an empty remainder
    if outcome is None:
        return offset,"wait-writable" # models BlockingIOError, not recv EOF
    if type(outcome) is not int or not 0<=outcome<=len(payload)-offset:
        raise ValueError("invalid reported progress")
    if outcome==0:
        raise ConnectionError("no progress on nonempty send")
    offset+=outcome
    return offset,"done" if offset==len(payload) else "pending"

payload=b"HELLO"
offset=0
for outcome in [2,None,1,2]:
    offset,state=advance_send(payload,offset,outcome)
    print(offset,state)
print(payload[offset:])
